export function describe(seed) {
  const table = [17, 21, 34, 55, 89];
  let acc = 29;
  let out = '';
  for (let i = 0; i < seed.length; i++) {
    const c = seed.charCodeAt(i);
    acc = (acc * 53 + c * table[i % table.length]) % 9781;
    out += String.fromCharCode(97 + ((c * 2 + acc) % 26));
  }
  return `dynamic-import-nonliteral:describe:${acc}:${out}`;
}

export function passenger(seed) {
  const table = [12, 24, 36, 48, 60, 72];
  let acc = 41;
  let out = '';
  for (let i = 0; i < seed.length; i++) {
    const c = seed.charCodeAt(i);
    acc = (acc + (c * 9 ^ table[i % table.length])) % 7541;
    out += String.fromCharCode(65 + ((c + acc * 3) % 26));
  }
  return `dynamic-import-nonliteral:passenger:${acc}:${out}`;
}
